// Generic WebGPU dispatcher for a GpuPlan program (crates/wasm): it knows nothing about networks.
// Each step is a WGSL kernel generated by shivai-core with its dispatch size and buffer bindings.

export interface Program {
  slots: number[] // bytes
  steps: { name: string; code: string; groups: [number, number, number]; bindings: ({ slot: number } | 'weights' | 'biases')[]; weights: number; biases: number }[]
  inputSlot: number
  outputSlot: number
  outputBytes: number
}

export async function requestDevice(): Promise<{ adapter: GPUAdapter; device: GPUDevice }> {
  const adapter = await navigator.gpu?.requestAdapter({ powerPreference: 'high-performance' })
  if (!adapter) throw new Error('WebGPU is unavailable in this browser.')
  const device = await adapter.requestDevice({
    requiredFeatures: adapter.features.has('shader-f16') ? ['shader-f16'] : [],
    requiredLimits: {
      maxBufferSize: adapter.limits.maxBufferSize,
      maxStorageBufferBindingSize: adapter.limits.maxStorageBufferBindingSize,
    },
  })
  return { adapter, device }
}

const align = (n: number) => Math.max(16, Math.ceil(n / 16) * 16)

export class GpuSession {
  private constructor(
    private device: GPUDevice,
    private program: Program,
    private slots: GPUBuffer[],
    private steps: { pipeline: GPUComputePipeline; bind: GPUBindGroup; groups: [number, number, number]; weights?: GPUBuffer; biases?: GPUBuffer }[],
    private readback: GPUBuffer,
  ) {}

  static async create(device: GPUDevice, program: Program): Promise<GpuSession> {
    const limit = Math.min(device.limits.maxBufferSize, device.limits.maxStorageBufferBindingSize)
    const largest = Math.max(...program.slots)
    if (largest > limit) throw new Error(`This model needs a ${Math.ceil(largest / 2 ** 20)} MiB GPU buffer; this device allows ${Math.floor(limit / 2 ** 20)} MiB.`)
    device.pushErrorScope('out-of-memory')
    device.pushErrorScope('validation')
    const usage = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC
    const slots = program.slots.map((bytes, i) => device.createBuffer({ size: align(bytes), usage, label: `slot ${i}` }))
    const steps = []
    for (const s of program.steps) {
      const module = device.createShaderModule({ label: s.name, code: s.code })
      const pipeline = await device.createComputePipelineAsync({ label: s.name, layout: 'auto', compute: { module, entryPoint: 'main' } })
      const weights = s.weights ? device.createBuffer({ size: align(s.weights * 4), usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST }) : undefined
      const biases = s.biases ? device.createBuffer({ size: align(s.biases * 4), usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST }) : undefined
      const entries = s.bindings.map((b, binding) => ({
        binding,
        resource: { buffer: b === 'weights' ? weights! : b === 'biases' ? biases! : slots[b.slot] },
      }))
      steps.push({ pipeline, bind: device.createBindGroup({ layout: pipeline.getBindGroupLayout(0), entries }), groups: s.groups, weights, biases })
    }
    const readback = device.createBuffer({ size: align(program.outputBytes), usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ })
    const validation = await device.popErrorScope()
    const oom = await device.popErrorScope()
    if (oom || validation) throw new Error(`GPU setup failed: ${(oom || validation)!.message}`)
    return new GpuSession(device, program, slots, steps, readback)
  }

  get bytes(): number {
    return this.slots.reduce((a, b) => a + b.size, 0) + this.steps.reduce((a, s) => a + (s.weights?.size ?? 0) + (s.biases?.size ?? 0), 0)
  }

  /** One fold's packed weights (GpuPlan.weights): every conv step's weights then biases, in order. */
  load(packed: Float32Array): void {
    let at = 0
    const write = (buffer: GPUBuffer, n: number) => {
      this.device.queue.writeBuffer(buffer, 0, packed, at, n)
      at += n
    }
    this.program.steps.forEach((p, i) => {
      const s = this.steps[i]
      if (!s.weights) return
      write(s.weights, p.weights)
      write(s.biases!, p.biases)
    })
    if (at !== packed.length) throw new Error('Weights do not match the program.')
  }

  /** Input slot bytes (GpuPlan.pack_input) -> output slot bytes (for GpuPlan.unpack_output). */
  async run(input: Uint8Array): Promise<Uint8Array> {
    const { device } = this
    device.queue.writeBuffer(this.slots[this.program.inputSlot], 0, input)
    device.pushErrorScope('out-of-memory')
    device.pushErrorScope('validation')
    try {
      // Separate command buffers avoid GPU timeouts; waiting every 8 bounds the queued work.
      for (const [i, s] of this.steps.entries()) {
        const encoder = device.createCommandEncoder()
        const pass = encoder.beginComputePass()
        pass.setPipeline(s.pipeline)
        pass.setBindGroup(0, s.bind)
        pass.dispatchWorkgroups(...s.groups)
        pass.end()
        device.queue.submit([encoder.finish()])
        if ((i + 1) % 8 === 0 || i + 1 === this.steps.length) await device.queue.onSubmittedWorkDone()
      }
      const encoder = device.createCommandEncoder()
      encoder.copyBufferToBuffer(this.slots[this.program.outputSlot], 0, this.readback, 0, align(this.program.outputBytes))
      device.queue.submit([encoder.finish()])
      await this.readback.mapAsync(GPUMapMode.READ)
      const out = new Uint8Array(this.readback.getMappedRange(0, this.program.outputBytes).slice(0))
      this.readback.unmap()
      return out
    } finally {
      const validation = await device.popErrorScope()
      const oom = await device.popErrorScope()
      if (oom || validation) throw new Error(`GPU inference failed: ${(oom || validation)!.message}`)
    }
  }

  release(): void {
    for (const b of [...this.slots, this.readback]) b.destroy()
    for (const s of this.steps) {
      s.weights?.destroy()
      s.biases?.destroy()
    }
  }
}
